train = readtable("train.csv") %[output:3d92d06d]
%%
summary(train) %[output:17644932]
%%
columnDataTypes = varfun(@iscell, train, OutputFormat="cell");
nonNumericCols = cell2mat(columnDataTypes);
nonNumColNames = train.Properties.VariableNames(nonNumericCols);

train = removevars(train, nonNumColNames) %[output:72e84947]
%%
% Get indices of all missing values
missingIdx = ismissing(train);

% Get indices of any rows that contain missing values
rowIdxWithMissing = any(missingIdx, 2);

% Show how many are missing from each column
numMissingByCol = sum(missingIdx) %[output:10bb6215]
%%
%[text] **Check columns with missing**
colsWithMissing = train.Properties.VariableNames(find(numMissingByCol)) %[output:565a4aa9]
%%
%[text] **Remove**
train = removevars(train, colsWithMissing) %[output:9dba411c]
%%
actualOutput = train.site_eui;
train = removevars(train, "site_eui") %[output:80d8558e]
%%
% Normalize Data %[task:6695]
newTable = normalize(train);

% Display results
figure %[output:9a574244]
tiledlayout(2,1); %[output:9a574244]
nexttile %[output:9a574244]
plot(train.floor_area,SeriesIndex=6,DisplayName="Input data") %[output:9a574244]
legend %[output:9a574244]
ylabel("floor_area",Interpreter="none") %[output:9a574244]

nexttile %[output:9a574244]
plot(newTable.floor_area,SeriesIndex=1,LineWidth=1.5, ... %[output:9a574244]
    DisplayName="Normalized data") %[output:9a574244]
legend %[output:9a574244]
ylabel("floor_area",Interpreter="none") %[output:9a574244]
set(gcf,NextPlot="new") %[task:6695]
%%
%[text] **Separate the dataset**
c = cvpartition(height(train), 'Holdout', 0.2) %[output:5de16cfd]

idxTrain = training(c) %[output:5fcfc55c]
trainingData = train(idxTrain,:) %[output:0edb6388]
trainingOutput = actualOutput(idxTrain) %[output:96526184]

idxTest = test(c) %[output:6dd93dae]
testingData = train(idxTest,:) %[output:805f19e2]
testingOutput = actualOutput(idxTest) %[output:33330826]

